"use strict";
// Fabrication parity with Altium Designer on a real project: the PiDP-11 I/O Expander
// (tests/fixtures/altium/pidp11-io-expander, BSD-2-Clause, see NOTICE) is imported exactly as
// File › Import › Altium does (PrjPcb + SchDoc + PcbDoc, project parameters included), its
// fabrication outputs are generated by the same analyse/plan/generate path the Fabrication
// Outputs dialog, output jobs and MCP generate_fabrication use, and every layer is compared
// geometrically (tests/formats/gerber-compare.cjs) with the Gerber and NC drill files Altium Designer
// 21.5.1 generated for that board (the upstream RevA release; altium-outputs-reva/, unmodified).
//
// Two import scenarios, both on every layer, drill and outline:
//   altium-rules  the "Use the board's rules" answer (AtriumImportRules.apply, MCP import_design
//                 source_rules:"use"): the converted rules drive mask and paste expansion, and
//                 Altium's stored pour fill is kept (it was poured under those rules).
//   as-imported   "Keep Waffle defaults": the 41 Altium rule records stay source records, so mask
//                 openings use Waffle's default expansion (the one asserted difference, KNOWN).
//
// Strict: counts are equal (flashes, draws, regions, drill hits per tool) and every deviation
// is at most EPS, the coordinate resolution of the two files (see TOL). The only other
// differences are listed in KNOWN and asserted to stay exactly what they are, so a change in
// either direction fails.
//
// Run: scripts/test-jsc.sh altium-fab-parity    (or node tests/formats/altium-fab-parity.cjs)
//      jsc tests/jsc-shim.js -- $PWD/tests/altium-fab-parity.cjs --print   for the per-layer table.
const assert = require("node:assert/strict"), fs = require("node:fs"), path = require("node:path");
globalThis.CFB = require("../../app/vendor/cfb.min.js");
if (!globalThis.performance) globalThis.performance = {now: () => Date.now()};
// The modules the editor has loaded when File › Fabrication Outputs runs on an imported board.
for (const f of ["model", "parts", "spatial", "sch-objects", "hierarchy", "board-shape", "board-shape-sources", "stackup", "impedance", "pcb-pours", "pcb-appearance", "zip", "vectorize",
  "pcb-text-rich", "pcb-text", "rigid-flex", "altium-rules", "pcb-draw", "component-classes", "net-intent", "signals", "query", "rules", "viastack", "polygon-pour", "import-link", "source-file", "sch-import", "pcb-import",
  "io", "connectivity", "bom", "import-rules", "fab-outputs"]) require(require("../support/app-source-paths.cjs").appFile(f + ".js"));
const C = require("./gerber-compare.cjs");
const A = Atrium, F = AtriumFabOutputs, PCB = AtriumPCBAppearance;
const FIX = path.join(__dirname, "../fixtures/altium/pidp11-io-expander"), REF = path.join(FIX, "altium-outputs-reva");
const PRINT = process.argv.includes("--print");
const started = Date.now();

