  "PiDP11IOExpander.GTS": "e51dae137bfa88289352f3569e230995bfdd9788a1eb0f7d5232a4c8de4992e5",
  "PiDP11IOExpander.GBS": "cb4577080898e12c384e1f7cd6b682aa7fbb82650bfe0b882f959f6be013fd23",
