const LAYERS = [
  {ext: "GTL", altium: "Top Layer", ff: "Copper,L1,Top", kind: "copper"},
  {ext: "GBL", altium: "Bottom Layer", ff: "Copper,L2,Bot", kind: "copper"},
  {ext: "GTS", altium: "Top Solder", ff: "Soldermask,Top", kind: "mask"},
  {ext: "GBS", altium: "Bottom Solder", ff: "Soldermask,Bot", kind: "mask"},
  {ext: "GTP", altium: "Top Paste", ff: "Paste,Top", kind: "paste"},
  {ext: "GBP", altium: "Bottom Paste", ff: "Paste,Bot", kind: "paste"},
  {ext: "GTO", altium: "Top Overlay", ff: "Legend,Top", kind: "silk", layer: "Silk"},
  {ext: "GBO", altium: "Bottom Overlay", ff: "Legend,Bot", kind: "silk", layer: "Bottom silk"},
  {ext: "GM1", altium: "Board Shape", ff: "Profile,NP", kind: "profile"}];
for (const L of LAYERS) assert.ok(new RegExp("^\\." + L.ext + "\\s+" + L.altium + "\\s*$", "m").test(EXTREP), "Altium maps ." + L.ext + " to " + L.altium);

// ---------------------------------------------------------------- import (File › Import › Altium) and generate
const FILES = ["PCB-PiDP11IOExpander.PrjPcb", "PiDP11IOExpander.SchDoc", "PiDP11IOExpander.PcbDoc"];
function importProject() {
  const read = FILES.map(name => AtriumIO.read(name, new Uint8Array(fs.readFileSync(path.join(FIX, name)))));
  const p = A.project("PiDP-11 I/O Expander"); p.documents = []; p.library = []; p.importNotes = [];
  for (const r of read) { p.documents.push(...(r.documents || [])); p.library.push(...(r.library || [])); p.importNotes.push(...(r.notes || [])); }
  // As the editor does (editor.js importFiles; MCP headless.js importDesign): the PrjPcb's
  // [ParameterN] values become project parameters, which board special strings read.
  const manifest = read.find(r => r.manifest)?.manifest;
  if (manifest?.parameters) p.parameters = {...manifest.parameters};
  AtriumImportLink.reconcile(p, p.documents);
  A.validate(p);
  return {p, pcb: p.documents.find(d => d.kind === "pcb")};
}
const DATE = new Date(Date.UTC(2026, 5, 15, 12));
function generate(scenario) {
  const {p, pcb} = importProject(), defs = new Map(p.library.map(d => [d.id, d]));
  let applied = null;
  if (scenario === "altium-rules") applied = AtriumImportRules.apply(pcb, p, defs);
  const out = F.build(p, pcb.id, {date: DATE});
  return {p, pcb, defs, out, applied, file: suffix => out.files.find(f => f.name.endsWith(suffix))?.content ?? null};
}

// Text boxes per overlay layer (Waffle's own text, from the same primitives the writer plots),
// so silkscreen is compared with and without text. Glyph shapes of Altium's stroke font are
// not Waffle's, so text is quantified on its own.
function textBoxes(model, layer, margin = .3) {
  const boxes = [], T = AtriumPCBText;
  const add = (s, frame) => {
    if (!s.text) return;
    const t = T.toPrimitives(s, {frame, layer});
    let b = null;
    const grow = (p, r) => { b = b ? [Math.min(b[0], p[0] - r), Math.min(b[1], p[1] - r), Math.max(b[2], p[0] + r), Math.max(b[3], p[1] + r)] : [p[0] - r, p[1] - r, p[0] + r, p[1] + r]; };
    for (const st of t.strokes) for (const p of st.points) grow(p, st.width / 2);
    for (const r of t.regions) for (const p of r) grow(p, 0);
    if (b) boxes.push([b[0] - margin, b[1] - margin, b[2] + margin, b[3] + margin]);
  };
  for (const i of model.doc.items) {
    if (i.kind === "label" && (i.layer || "Silk") === layer) add(T.projectItem(i,model.project),null);
    if (i.kind !== "part") continue;
    const fp = model.defs.get(i.def)?.footprint;
    for (const s of fp?.shapes || []) if ((s.kind === "text" || s.kind === "label") && PCB.shapeLayer(i, s) === layer) add(A.special(s, i), i);
    for (const a of PCB.sourceLabels(model.doc, i) || []) if (a.layer === layer && i[a.field]) add(PCB.annotationText(i,a), i);
  }
  // Gerber coordinates: the writer's origin (lower-left of the outline), Y up.
  const ext = model.extents, ox = ext[0], oy = ext[3];
  return boxes.map(b => [b[0] - ox, oy - b[3], b[2] - ox, oy - b[1]]);
}
const inBoxes = boxes => p => boxes.some(b => p[0] >= b[0] && p[0] <= b[2] && p[1] >= b[1] && p[1] <= b[3]);
const rects = boxes => boxes.map(b => ({k: "poly", rings: [[[b[0], b[1]], [b[2], b[1]], [b[2], b[3]], [b[0], b[3]]]], dark: true}));

// ---------------------------------------------------------------- MCP: same files as the app
// tests/formats/altium-fab-parity-mcp.py imports the fixture with the MCP server (import_design,
// source_rules:"use"), writes its outputs with generate_fabrication and runs this file with
// --mcp-dir=<output dir> --mcp-stem=<file stem>: every Gerber and drill file must equal, byte for
// byte apart from the creation date, what the app writes in the altium-rules scenario, so the
// parity below holds for MCP and output jobs as well.
const MCP_DIR = process.argv.find(a => a.startsWith("--mcp-dir="))?.slice(10);
if (MCP_DIR) {
  const stem = process.argv.find(a => a.startsWith("--mcp-stem="))?.slice(11) || "PiDP", G = generate("altium-rules");
  const norm = t => t.replace(/\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:?\d\d)?/g, "<date>");
  const files = G.out.files.filter(f => f.kind === "gerber" || f.kind === "drill"), own = G.pcb.name;
  assert.ok(files.length >= 10, "Gerber and drill files planned");
  for (const f of files) {
    const name = stem + f.name.slice(own.length);
    assert.ok(fs.existsSync(path.join(MCP_DIR, name)), "MCP wrote " + name);
    const mcp = norm(fs.readFileSync(path.join(MCP_DIR, name), "utf8")).split("\n"), app = norm(f.content).split("\n");
    const i = app.findIndex((l, k) => l !== mcp[k]);
    assert.ok(i < 0 && app.length === mcp.length, name + " differs from the app's output at line " + (i + 1) + ": " + JSON.stringify(app[i]) + " vs " + JSON.stringify(mcp[i]));
  }
  console.log("altium-fab-parity (MCP): " + files.length + " Gerber and drill files from generate_fabrication equal the app's Fabrication Outputs");
  return;
}

// ---------------------------------------------------------------- tolerances and known differences
const UM = .001;
// EPS: the coordinate resolution of the two files. Altium writes inch 2:5 (one step = 0.254 µm),
// rounding coordinates to the nearest step and aperture sizes up to the next one (a 22.835 mil pad
// is written 0.02284 in, 0.137 µm over); Waffle writes mm 4:6 (0.001 µm). No pair of files in these
// formats can agree more closely than one Altium step plus one Waffle step, so EPS is the tolerance
// for everything geometric: flash centres and sizes, draw centrelines and widths, region boundaries,
// drill positions and diameters, the profile. Nothing else is tolerated.
const EPS = .254 * UM + .001 * UM;
// CHORD: arcs (G02/G03) are compared as polylines within 0.01 µm of the true arc.
const PIXEL = .005, PHASE = Math.SQRT2 - 1, CHORD = .01 * UM;
const TOL = {
  flashPos: EPS, flashSize: EPS, vector: EPS, width: EPS, drillPos: EPS, outline: EPS,
  // Drill diameters: Waffle's tool table prints mm with 3 decimals (tools are keyed on the printed
  // size, review L2), so a 62 mil = 1.5748 mm hole prints 1.575: half a step (0.5 µm) more.
  drillDia: .0005 + EPS,
  // Raster (5 µm pixels, centres shifted by PHASE of a pixel off the round CAD coordinates): an
  // edge moved by less than EPS can flip at most the pixels it crosses, so no XOR pixel may lie
  // more than one pixel from the other image, and the mean edge displacement (XOR area / edge
  // length) may not exceed EPS.
  rasterDev: PIXEL + 1e-9, meanDev: EPS};
const KNOWN = {
  // Altium writes a region's holes as separate clear-polarity regions; Waffle joins them to the
  // outline with cut-ins (spec 2024.05 §4.10.3). Same image, different region counts.
  regionHoles: {GTO: {ref: 27, out: 18}},
  // As imported with Waffle's default rules ("Keep Waffle defaults"), solder mask uses Waffle's
  // default 4 mil expansion instead of the board's 3.937 mil rule: every opening is 2 x 1.6 µm
  // larger. With the board's rules (altium-rules) the openings are exact.
  maskDefault: 2 * (.1016 - 3.937 * .0254),
  // Waffle draws its own stroke contours. Checked Altium project strings use native
  // cell spacing. Their three printed run extents are checked separately below.
  textInk: .015,
  textXor: {GTO: 4.85, GBO: 2.27},
};

// ---------------------------------------------------------------- compare
const um = v => Number.isNaN(v) ? "-" : v === Infinity ? ">2000" : (v * 1e3).toFixed(3);
const mm2 = v => v.toFixed(4);
const table = [];
const drillRef = C.parseExcellon(refText("TXT"));
const holes = C.holeShapes([drillRef]);
const widths = parsed => [...new Set(parsed.draws.map(d => Math.round(d.width / EPS)))].sort((a, b) => a - b);
function compareScenario(scenario) {
  const G = generate(scenario), result = {scenario, layers: {}};
  if (G.applied) result.applied = G.applied;
  for (const L of LAYERS) {
    const ref = C.parseGerber(refText(L.ext), {chord: CHORD}), text = G.file("." + L.ext);
    if (!text) {
      // Waffle leaves an empty optional layer out of the plan; Altium writes an empty file.
      result.layers[L.ext] = {missing: true, refObjects: ref.flashCount + ref.drawCount + ref.regionCount, outFeatures: G.out.model.layers.get(L.kind === "paste" ? (L.ext === "GTP" ? "Top paste" : "Bottom paste") : L.layer)?.length || 0};
      table.push([scenario, L.ext, "empty in Altium; no objects, no file in Waffle", "", "", "", "", ""]);
      continue;
    }
    const out = C.parseGerber(text, {chord: CHORD});
    assert.equal(/%TF\.FileFunction,([^*]*)\*%/.exec(text)?.[1].replace(/,(Signal|Plane|Mixed)$/, ""), L.ff, L.ext + " file function");
    const boxes = L.kind === "silk" ? textBoxes(G.out.model, L.layer) : null;
    const t0 = Date.now();
    const r = C.compareLayer(ref, out, {pixel: PIXEL, phase: PHASE, mask: boxes ? rects(boxes) : null, exclude: boxes ? inBoxes(boxes) : null, rawDistance: !boxes});
    if (PRINT) console.log("  " + scenario + " " + L.ext + " " + (Date.now() - t0) + " ms");
    const v = r.vector, row = {raw: r.raw, masked: r.masked, flashes: r.flashes, vector: v, refStats: r.refStats, outStats: r.outStats, widths: [widths(ref), widths(out)]};
    if (boxes) row.text = {boxes: boxes.length, xor: r.raw.xorArea - r.masked.xorArea, refInk: r.raw.areaA - r.masked.areaA, outInk: r.raw.areaB - r.masked.areaB};
    result.layers[L.ext] = row;
    const vmax = Math.max(v.draws.refToOut.max, v.draws.outToRef.max, v.regions.refToOut.max, v.regions.outToRef.max), img = r.masked || r.raw;
    table.push([scenario, L.ext, r.refStats.flashes + "/" + r.outStats.flashes + " " + r.refStats.draws + "/" + r.outStats.draws + " " + r.refStats.regions + "/" + r.outStats.regions,
      um(r.flashes.maxPosDev) + "/" + um(r.flashes.maxSizeDev), um(vmax), mm2(img.xorArea) + " (" + um(img.meanDev) + ")", um(img.maxDev), row.text ? mm2(row.text.xor) + " (ink " + mm2(row.text.refInk) + " / " + mm2(row.text.outInk) + ")" : ""]);
  }
  const files = G.out.files.filter(f => f.kind === "drill").map(f => C.parseExcellon(f.content));
  const d = C.compareDrills(drillRef, {hits: files.flatMap(x => x.hits), slots: files.flatMap(x => x.slots)});
  result.drill = d;
  table.push([scenario, "drill", d.ref + "/" + d.out + " hits", um(d.maxPosDev) + "/" + um(d.maxDiaDev), "", "", "", JSON.stringify(d.refTools) === JSON.stringify(d.outTools) ? "tools equal" : "TOOLS DIFFER"]);
  result.outline = C.compareOutlines(C.parseGerber(refText("GM1")), C.parseGerber(G.file(".GM1")));
  table.push([scenario, "outline", "", "", um(result.outline.maxDev), "width " + um(Math.abs(result.outline.refWidth - result.outline.outWidth)), "", ""]);
  result.G = G;
  return result;
}
const rules = compareScenario("altium-rules"), asImported = compareScenario("as-imported");

// Read the saved native member bytes back into a separate model. Both rule choices
// retain the physical artwork; node IDs and source provenance are independent.
for (const name of ["sexpr", "format-2-codec", "format-2-units", "format-2-values", "format-2-model",
  "import-sidecars", "import-reports", "revisions", "undo-store"]) require(require("../support/app-source-paths.cjs").appFile(name + ".js"));
function checkNativeCopper(source, edit) {
  const M = AtriumFormat2Model, C = AtriumFormat2, P = AtriumPolygonPour;
  const input = A.clone(source.p);
  if (edit) AtriumRevisions.freeze(input, {letter:"A", date:"2026-06-15", time:DATE.getTime()});
  const native = M.fromEditor(input), root = M.parse(C.serialize(native.manifest));
  const files = new Map(native.files.map(m => [m.path, m.file]));
  function reopen(manifest, membersByPath = files) {
    const {project, members} = M.manifest(M.parse(C.serialize(manifest)));
    for (const ref of members) {
      if (ref.kind !== "library" && !Object.hasOwn(C.documentSuffix, ref.kind)) continue;
      const file = M.parse(C.serialize(membersByPath.get(ref.path)));
      if (ref.kind === "library") project.library.push(M.library(file));
      else project.documents.push(M.document(file, {name:ref.name}));
    }
    return project;
  }
  const project = reopen(root);
  const board = project.documents.find(d => d.kind === "pcb"), defs = new Map(project.library.map(d => [d.id, d]));
  const copper = () => P.outputCopper(board, defs, {project, solve:false});
  const regions = rows => rows.map(r => [r.layer, r.net, r.count, r.data]);
  const original = regions(source.pcb.pcbDrawing.pours);
  const clean = JSON.stringify(board);
  assert.equal(copper().state, "current");
  assert.deepEqual(regions(copper().regions), original, "all five source-owned region envelopes survive");
  assert.equal(board.pcbDrawing.pourSignatures, undefined);
  assert.equal(board.pcbDrawing.pourSignatureVersion, undefined);
  const film = (out, ext) => out.files.find(f => f.name.endsWith(ext)).content.match(/G36\*[\s\S]*?G37\*/g);
  const plotted = F.build(project, board.id, {date:DATE});
  for (const ext of [".GTL", ".GBL"]) assert.deepEqual(film(plotted,ext), film(source.out,ext), ext + " retains exact drawn copper polygons");
  assert.equal(JSON.stringify(board), clean, "opening, plotting and inspecting signed copper writes nothing to the board");
  if (!edit) return;

  const assets = new Map(native.assets.map(a => [a.path, a.bytes]));
  const [release] = M.manifest(root).releases;
  const archive = M.snapshot(M.parse(assets.get(M.assetPath(release.snapshot))));
  const members = new Map(archive.members.map(m => [m.logicalPath, M.parse(assets.get(m.path))]));
  const frozen = reopen(members.get(archive.root.logicalPath), members);
  const frozenBoard = frozen.documents.find(d => d.id === board.id);
  const frozenCopper = P.outputCopper(frozenBoard, new Map(frozen.library.map(d => [d.id,d])), {project:frozen,solve:false});
  assert.equal(frozenCopper.state, "current", "a named release retains the same authenticated source copper");
  assert.deepEqual(regions(frozenCopper.regions), original);

  // Exercise the same editor journal and import-report action used by Discard and Undo.
  const R = AtriumImportReports, S = AtriumImportSidecars, U = AtriumUndoStore;
  const session = {}, history = [], future = [];
  U.reset();
  const mark = () => U.mark(project, {current:board.id, imports:R.capture()});
  const host = {project:() => project, fileSession:() => session, on(){}, registerAction(){},
    edit(fn,label) { U.checkpoint(history, future, mark(), label); fn(); U.record(project); }};
  R.attach(host);
  const inputs = FILES.map(name => {
    const bytes = new Uint8Array(fs.readFileSync(path.join(FIX,name)));
    return {name, bytes, sha256:C.sha256(bytes)};
  });
  const index = S.prepareSync([{scopeId:"public-pidp", documents:[board.id], names:FILES,
    report:{translator:"altium",kinds:[]}, provenance:{files:inputs}}]);
  const ref = index.refs[0], withIndex = C.edit(root, {put:index.refs});
  function storedRegions(manifest) {
    const saved = reopen(manifest), pcb = saved.documents.find(d => d.kind === "pcb");
    return regions(P.outputCopper(pcb, new Map(saved.library.map(d => [d.id,d])), {project:saved,solve:false}).regions);
  }
  R.installRetained(session, [S.restore(S.parse(index.files.get(ref.path),ref))]);
  const undo = () => {
    const previous = U.jump(history, future, mark(), -1);
    assert.ok(previous); R.restore(session, previous.imports); U.touch(project);
  };
  assert.equal(R.discard(ref.id), true);
  assert.equal(R.retained().length, 0);
  const discarded = M.detachImports(withIndex, [ref.id]);
  assert.equal(C.sha256(C.serialize(discarded)), C.sha256(C.serialize(root)));
  assert.deepEqual(storedRegions(discarded), original, "a cold read after Discard needs only native board members");
  assert.deepEqual(regions(copper().regions), original);
  undo();
  assert.equal(R.retained()[0].scopeId, ref.id);
  const restored = C.edit(discarded, {put:[ref]});
  assert.equal(C.sha256(C.serialize(restored)), C.sha256(C.serialize(withIndex)));
  assert.deepEqual(storedRegions(restored), original);
  assert.deepEqual(regions(copper().regions), original);
  const top = board.items.find(i => i.kind === "polygon" && i.layer === "Top");
  const bottom = board.items.find(i => i.kind === "polygon" && i.layer === "Bottom");
  host.edit(() => { board.items.find(i => i.kind === "track" && i.layer === "Top").points[0][0] += .5; }, "Move top track");
  assert.deepEqual(copper().pending, [top.id], "moving top copper leaves the bottom contour valid");
  const afterMove = JSON.stringify(board), refill = P.outputCopper(board,defs,{project});
  assert.deepEqual(refill.filled, [top.id]);
  assert.deepEqual(regions(refill.regions.filter(r => r.layer === "Bottom")), original.filter(r => r[0] === "Bottom"));
  assert.equal(JSON.stringify(board), afterMove, "a required refill for output is detached");
  undo();
  assert.deepEqual(regions(copper().regions), original);
  host.edit(() => { board.outline[0][0] += .25; }, "Move board edge");
  assert.deepEqual(copper().pending.slice().sort(), [top.id, bottom.id].sort());
  undo();
  assert.deepEqual(regions(copper().regions), original);
  host.edit(() => {
    const region = board.pcbDrawing.pours.find(r => r.polygon === bottom.id);
    region.data = board.pcbDrawing.pours.find(r => r.polygon === top.id).data;
  }, "Replace a stored contour");
  assert.deepEqual(copper().pending, [bottom.id], "copper with a mismatched contour fingerprint is stale");
  undo();
  assert.equal(JSON.stringify(board), clean);
  assert.deepEqual(regions(copper().regions), original);
}
checkNativeCopper(rules.G, true);
checkNativeCopper(asImported.G, false);
if (PRINT) {
  console.log("scenario      layer    flashes draws regions ref/out  flash pos/size µm  vector max µm  XOR mm² (mean µm)  raster max µm  text XOR mm²");
  for (const r of table) console.log(r[0].padEnd(13), r[1].padEnd(8), String(r[2]).padEnd(32), String(r[3]).padEnd(18), String(r[4]).padEnd(14), String(r[5]).padEnd(18), String(r[6]).padEnd(14), r[7]);
}

// ---------------------------------------------------------------- assertions (both scenarios)
const rasterOk = (img, what) => assert.ok(img.meanDev <= TOL.meanDev && img.maxDev <= TOL.rasterDev,
  what + " raster: XOR " + mm2(img.xorArea) + " mm², mean " + um(img.meanDev) + " µm, max " + um(img.maxDev) + " µm");
const vectorOk = (r, what) => {
  for (const k of ["draws", "regions"]) for (const w of ["refToOut", "outToRef"]) assert.ok(r.vector[k][w].max <= TOL.vector, what + " " + k + " " + w + " deviation " + um(r.vector[k][w].max) + " µm at " + r.vector[k][w].at);
  assert.deepEqual(r.widths[1], r.widths[0], what + " draw widths (aperture dictionary of the draws)");
};
const flashesOk = (r, what, sizeDev = 0) => {
  const f = r.flashes;
  assert.ok(f.matched === f.ref && f.out === f.ref, what + " flashes " + f.ref + "/" + f.out + " (" + f.matched + " matched): missing " + JSON.stringify(f.missing.slice(0, 4)) + " extra " + JSON.stringify(f.extra.slice(0, 4)));
  assert.ok(f.maxPosDev <= TOL.flashPos, what + " flash positions " + um(f.maxPosDev) + " µm");
  assert.ok(Math.abs(f.maxSizeDev - sizeDev) <= TOL.flashSize, what + " flash sizes " + um(f.maxSizeDev) + " µm (expected " + um(sizeDev) + ")");
};
for (const S of [rules, asImported]) {
  const L = S.layers, name = S.scenario;
  // Drill: identical holes (count per tool, positions, diameters, plating), no slots.
  const d = S.drill;
  assert.deepEqual(d.outTools, d.refTools, name + ": drill tools and hit counts");
  assert.ok(d.matched === d.ref && d.out === d.ref, name + ": drill hits " + d.ref + "/" + d.out + " (" + d.matched + " matched)");
  assert.deepEqual(d.wrong, [], name + ": drill diameters and plating");
  assert.ok(d.maxPosDev <= TOL.drillPos && d.maxDiaDev <= TOL.drillDia, name + ": drill deviation " + um(d.maxPosDev) + " / " + um(d.maxDiaDev) + " µm");
  assert.deepEqual(d.slots, {ref: 0, out: 0});
  // Board outline.
  const o = S.outline;
  assert.ok(o.maxDev <= TOL.outline, name + ": outline deviation " + um(o.maxDev) + " µm");
  assert.ok(Math.abs(o.refWidth - o.outWidth) <= TOL.outline, name + ": profile line width");
  for (let k = 0; k < 4; k++) assert.ok(Math.abs(o.refBox[k] - o.outBox[k]) <= TOL.outline, name + ": outline box and origin");
  assert.ok(Math.abs(o.refLength - o.outLength) <= TOL.outline, name + ": outline length");
  vectorOk(L.GM1, name + " GM1"); rasterOk(L.GM1.raw, name + " GM1");
  // Copper: Altium's stored pour fill, pads (lands as large as their hole included), vias, tracks, free regions.
  for (const ext of ["GTL", "GBL"]) {
    const r = L[ext];
    flashesOk(r, name + " " + ext);
    vectorOk(r, name + " " + ext);
    assert.deepEqual(r.outStats, r.refStats, name + " " + ext + " flash, draw and region counts");
    rasterOk(r.raw, name + " " + ext);
  }
  // Solder mask: same openings; as imported they are larger by the default-expansion difference only.
  for (const ext of ["GTS", "GBS"]) {
    flashesOk(L[ext], name + " " + ext, name === "as-imported" ? KNOWN.maskDefault : 0);
    if (name !== "as-imported") rasterOk(L[ext].raw, name + " " + ext);
  }
  // Paste: identical; bottom paste is empty in both.
  flashesOk(L.GTP, name + " GTP"); rasterOk(L.GTP.raw, name + " GTP");
  assert.ok(L.GBP.missing && L.GBP.refObjects === 0 && L.GBP.outFeatures === 0, name + ": bottom paste is empty in both");
  // Overlays: everything that is not text matches (component outlines, the logo and other
  // regions, pin markers); text matches in position, size and ink, its glyphs are Waffle's font.
  for (const ext of ["GTO", "GBO"]) {
    const r = L[ext];
    vectorOk(r, name + " " + ext + " non-text");
    rasterOk(r.masked, name + " " + ext + " non-text");
    assert.equal(r.outStats.flashes, r.refStats.flashes, name + " " + ext + " flashes");
    const holes = KNOWN.regionHoles[ext];
    assert.deepEqual([r.refStats.regions, r.outStats.regions], holes ? [holes.ref, holes.out] : [r.refStats.regions, r.refStats.regions], name + " " + ext + " regions (holes as clear regions vs cut-ins)");
    assert.ok(Math.abs(r.text.refInk - r.text.outInk) <= KNOWN.textInk * r.text.refInk, name + " " + ext + " text ink " + mm2(r.text.refInk) + " vs " + mm2(r.text.outInk) + " mm²");
    assert.ok(r.text.xor <= KNOWN.textXor[ext], name + " " + ext + " text glyph XOR " + mm2(r.text.xor) + " mm² (font; regression guard)");
  }
}
// Special strings: the bottom overlay's three strings are filled from the PrjPcb parameters.
{
  const labels = rules.G.pcb.items.filter(i => i.kind === "label" && i.layer === "Bottom silk").map(i => F.specialText(rules.G.p, i.text)).sort();
  assert.deepEqual(labels, ["PiDP-11 I/O Expander", "Revision A", "https://github.com/sstallion/PCB-PiDP11IOExpander"], "GBO special strings substituted");
  const native=C.parseGerber(fs.readFileSync(path.join(REF,"PiDP11IOExpander.GBO"),"utf8"));
  const output=C.parseGerber(rules.G.file(".GBO"));
  // Isolate each line by the gaps between the three printed rows (Gerber Y up).
  const extent=(plot,y0,y1)=>{
    const box=[Infinity,Infinity,-Infinity,-Infinity];
    for(const draw of plot.draws)if(draw.points.every(p=>p[1]>y0 && p[1]<y1)){
      for(const [x,y] of draw.points){
        box[0]=Math.min(box[0],x-draw.width/2);box[1]=Math.min(box[1],y-draw.width/2);
        box[2]=Math.max(box[2],x+draw.width/2);box[3]=Math.max(box[3],y+draw.width/2);
      }
    }
    return box;
  };
  for(const [name,low,high] of [["URL",0,1.8],["revision",1.8,2.8],["title",2.8,4.1]]){
    const a=extent(native,low,high),b=extent(output,low,high);
    for(let i=0;i<4;i++)assert.ok(Math.abs(a[i]-b[i])<=EPS,"GBO "+name+" ink edge "+i+": "+a[i]+" vs "+b[i]);
  }
}
// The board's rules kept Altium's pour fill (no repour): poured copper is Altium's.
assert.ok(rules.applied.converted > 0 && rules.applied.kept > 0 && rules.applied.repoured === 0, "rules adopted, stored fill kept: " + JSON.stringify(rules.applied));
const elapsed = Date.now() - started;
console.log("altium-fab-parity: PiDP-11 I/O Expander vs Altium Designer 21.5.1 RevA outputs: drill " + rules.drill.matched + "/" + rules.drill.ref +
  " hits, every layer within " + um(EPS) + " µm (format resolution), text glyph XOR GTO " + mm2(rules.layers.GTO.text.xor) + " / GBO " + mm2(rules.layers.GBO.text.xor) + " mm², " + elapsed + " ms");
module.exports = {asImported, rules, table, LAYERS, TOL, KNOWN, EPS};
